SELECT coalesce(json_agg(a), '[]') FROM (SELECT pid,host(client_addr) AS client,xact_start::text,query_start::text,state,wait_event_type,wait_event,
        (extract(epoch FROM clock_timestamp()-query_start)*1000)::int AS waited_ms
       FROM pg_stat_activity WHERE usename='r_totals__counter' AND state='active' AND wait_event_type='Lock' AND position('DO UPDATE SET total=counts.total+1' in query)>0) a;

